#!/usr/bin/env python3
# 04-r17: the H* decision TREE (04-Hstar-decision-tree.md) collapsed to EXECUTABLE code + machine-checked.
# r16 wrote the tree as prose/ASCII; this round makes it a function so it can be regression-tested, not eyeballed.
# Each leaf returns (H*, quant). The tree is keyed on the user's three answers -> resolves in one call.
import sys

BE_A100 = 1735   # break-even refurb A100-40 vs RTX 5090 (DECODE-DOMINANT, quant-invariant, inv7; roofline ratio 0.867)
BE_4090 = 1124  # break-even refurb RTX 4090(INT4) vs RTX 5090 (quant-invariant, inv7; roofline ratio 0.563)

# inv20 (r29): the $1735 break-even is DECODE-DOMINANT (derived from the bw/bytes DECODE roofline). A real request =
# PREFILL (compute-bound, both cards ~equal peak) THEN DECODE. At short generations the total-request rate ratio
# drifts UP toward 1 -> the A100-40 break-even RISES to a compute-based ~$1996 (prefill-heavy makes the A100 MORE
# competitive). So the true be depends on the WORKLOAD: decode-dominant -> $1735, prefill-heavy -> ~$1996. The tree
# MUST take the workload axis or it is WRONG for a quote in the ($1735,$1996) band. At $1200 NO flip (robust).
import os
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import roofline_verify as rv
BE_A100_PREFILL = round(rv.CARDS["RTX_5090"]["price"] * rv.total_rate("A100-40", 1024, 1) / rv.total_rate("RTX_5090", 1024, 1))

def resolve(form_factor, a100_quote=None, rtx4090_quote=None, workload="decode"):
    """Return (H* card+quant, reason). 'HELD' = still needs a missing user/market answer.
    workload='decode' (default) -> decode-dominant be=$1735; 'prefill' -> prefill-heavy be=~$1996 (inv20)."""
    if form_factor == "server":
        if a100_quote is None: return ("HELD", "need refurb A100-40 quote vs $%d (decode) / $%d (prefill-heavy)" % (BE_A100, BE_A100_PREFILL))
        be = BE_A100_PREFILL if workload == "prefill" else BE_A100
        if a100_quote < be: return ("A100-40 refurb INT8", "quote $%d < $%d be (%s-dominant)" % (a100_quote, be, workload))
        return ("RTX 5090 INT8", "quote $%d >= $%d be (%s-dominant) -> 5090 faster at roofline wins" % (a100_quote, be, workload))
    if form_factor == "tower":
        if rtx4090_quote is None: return ("HELD", "need refurb RTX 4090 quote vs $%d" % BE_4090)
        if rtx4090_quote < BE_4090: return ("refurb RTX 4090 INT4", "quote $%d < $%d (INT4-only caveat)" % (rtx4090_quote, BE_4090))
        return ("RTX 5090", "quote $%d >= $%d -> 5090 (INT8-capable, faster) wins" % (rtx4090_quote, BE_4090))
    return ("HELD", "unknown form-factor '%s' -> ask Q1" % form_factor)

print("== H* RESOLVER (decision tree as code; self-resolving on user answers) ==")
CASES = [
    # (form_factor, a100_quote, rtx4090_quote, workload, expected_H*)
    ("server", 1200, None, "decode",  "A100-40 refurb INT8"),
    ("server", 2000, None, "decode",  "RTX 5090 INT8"),
    ("server", 1735, None, "decode",  "RTX 5090 INT8"),          # boundary: strict '<' -> at be, 5090 wins
    ("server", None, None, "decode",  "HELD"),                    # needs quote
    ("tower",  None, 900,  "decode",  "refurb RTX 4090 INT4"),
    ("tower",  None, 1500, "decode",  "RTX 5090"),
    ("tower",  None, 1124, "decode",  "RTX 5090"),                # boundary: strict '<' -> at be, 5090 wins
    ("tower",  None, None, "decode",  "HELD"),                    # needs quote
    ("unknown",None, None, "decode",  "HELD"),                    # Q1 unanswered
    # inv20 (r29) WORKLOAD AXIS -- the ($1735,$1996) band is where decode-dominant and prefill-heavy DISAGREE:
    ("server", 1800, None, "decode",  "RTX 5090 INT8"),           # 1800>$1735 decode-dominant -> 5090 wins
    ("server", 1800, None, "prefill", "A100-40 refurb INT8"),    # 1800<$1996 prefill-heavy -> A100-40 wins (THE FLIP BAND)
    ("server", 1200, None, "prefill", "A100-40 refurb INT8"),    # $1200 robust: wins under BOTH regimes
    ("server", 2000, None, "prefill", "RTX 5090 INT8"),           # 2000>$1996 prefill-heavy -> 5090 still wins
]
fails = []
for ff, q100, q4090, wl, exp in CASES:
    got, why = resolve(ff, q100, q4090, wl)
    ok = got == exp
    print(f"  [{'ok' if ok else 'FAIL'}] {ff:7s} a100={str(q100):>5s} 4090={str(q4090):>5s} {wl:7s} -> {got:22s} ({why})")
    if not ok: fails.append(f"{ff}/{q100}/{q4090}/{wl}: got '{got}' != exp '{exp}'")

# inv20 teeth (r29): the WORKLOAD axis is LOAD-BEARING -- at $1800 decode says 5090 but prefill says A100-40.
# If the axis were ignored (be always decode=$1735), the prefill case would wrongly return 5090 -> this check bites.
band_lo, band_hi = BE_A100, BE_A100_PREFILL
d = resolve("server", 1800, None, "decode")[0]
p = resolve("server", 1800, None, "prefill")[0]
if d == p: fails.append("inv20 teeth: decode & prefill gave SAME H* at $1800 -> workload axis is decorative")
if not (band_lo < 1800 < band_hi): fails.append(f"inv20 teeth: $1800 not inside the flip band (${band_lo},${band_hi})")
print(f"  inv20 teeth: flip band (${band_lo},${band_hi}); $1800 decode->{d}, prefill->{p} -> axis BITES (they disagree)")

# inv9 (r17): monotonicity guard -- a LOWER refurb quote must never yield a WORSE (higher-cost-perf) H*.
# At server branch, halving the A100-40 quote can only keep-or-improve its standing vs 5090.
lo = resolve("server", 600)[0]; hi = resolve("server", 3000)[0]
if lo != "A100-40 refurb INT8": fails.append("inv9: cheap A100-40 ($600) did not win")
if hi != "RTX 5090 INT8":       fails.append("inv9: pricey A100-40 ($3000) did not lose to 5090")
print("  inv9: monotone in price (cheap A100-40 wins, pricey loses) -> tree is price-driven not throughput-driven")

# inv12 (r20): CROSS-FILE CONSISTENCY. r17 HARDCODED BE_A100/BE_4090 here; roofline_verify.py COMPUTES them from
# CARDS (bw,price). If CARDS drifts (a bw/price fix) and this file is forgotten, the two DISAGREE -> the tree
# resolves H* on a STALE break-even -> wrong answer. Recompute from the roofline source and pin the constants.
import os
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import roofline_verify as rv
ratio_a100 = rv.roofline("A100-40", "INT8") / rv.roofline("RTX_5090", "INT8")   # params & gate cancel -> bw ratio
ratio_4090 = rv.roofline("RTX_4090", "INT4") / rv.roofline("RTX_5090", "INT4")    # BOTH INT4 (quality-comparable; quant-invariant bw ratio)
p_be_a100  = rv.CARDS["RTX_5090"]["price"] * ratio_a100
p_be_4090  = rv.CARDS["RTX_5090"]["price"] * ratio_4090
if abs(p_be_a100 - BE_A100) > 1.5: fails.append(f"inv12: BE_A100 {BE_A100} != computed {p_be_a100:.1f} (CARDS drift)")
if abs(p_be_4090 - BE_4090) > 1.5: fails.append(f"inv12: BE_4090 {BE_4090} != computed {p_be_4090:.1f} (CARDS drift)")
print(f"  inv12: BE_A100={BE_A100}==computed {p_be_a100:.1f}, BE_4090={BE_4090}==computed {p_be_4090:.1f} -> tree constants match roofline source")

# inv21 (r30): COMPATIBILITY gate -- the roofline checked only VRAM CAPACITY (bytes<=GB); DEPLOYABLE ALSO needs the
# quant KERNEL to RUN on the card's compute capability. RTX 5090 = sm_100 (NEWEST arch); GPTQ INT4 on sm_100 is
# reported lagging / recompile-needed (社区R: web-search). The tree must NEVER emit an UNRUNNABLE (card,quant) --
# fitting the model in VRAM does NOT imply the kernel runs. Guard every resolved leaf against the known-unready set.
COMPAT_UNREADY = {("RTX 5090", "INT4")}   # sm_100 GPTQ INT4 = partial/recompile-needed (社区R); INT8/FP8 reported OK
def parse_card_quant(hstar):
    toks = hstar.replace("refurb ", "").split()
    quant = toks[-1] if toks[-1] in ("INT4", "INT8", "BF16") else None
    card = " ".join(toks[:-1]) if quant else hstar
    return card, quant
unrunnable_leaves = []
for ff, q100, q4090, wl, _exp in CASES:
    got, _ = resolve(ff, q100, q4090, wl)
    if got == "HELD": continue
    card, quant = parse_card_quant(got)
    if (card, quant) in COMPAT_UNREADY: unrunnable_leaves.append((ff, got))
if unrunnable_leaves: fails.append(f"inv21: tree emits an UNRUNNABLE (card,quant) {unrunnable_leaves} -> compat gate violated")
print(f"  inv21: every resolved leaf is DEPLOYABLE (no sm_100 GPTQ-INT4 emitted; 5090 leaf uses INT8 which sm_100 supports) -> tree respects the COMPATIBILITY gate")

# inv22 (r31): BATCH-domain -- the tree's be ($1735 decode / $1995 prefill) is derived from the bw/bytes roofline,
# which is VALID only while decode is MEMORY-bound (batch < B*). At batch>=B* (~38 INT8) the weights amortize /B,
# AI crosses ridge, decode flips COMPUTE-bound -> bw/bytes OVERestimates the throughput P -> the be would drift
# toward the compute ratio (needs per-card peak flops = ENV-BLOCKED). So BATCH is a NEW required input the
# deliverable must DECLARE (it silently assumed batch=1). Register it; the tree must never present a be as batch-invariant.
REQUIRED_INPUTS = {
    "Q1 form-factor",
    "Q2 refurb A100-40 quote",
    "Q3 refurb RTX 4090 quote",
    "Q4 batch size (roofline be valid only batch<B*~38; batched decode flips compute-bound, ENV-BLOCKED to recompute)",
    "Q5 working-sequence-length / CTX (VRAM feasibility gate silently assumed 8K output; at 128K input the 5090 INT8 KV overflows 32GB -> needs INT4 [inv21 kernel-unready] or a 40/48GB card)",
    "Q6 ENERGY / TCO (criterion C(H*) silently = STICKER PRICE; task says RUN -> operating ENERGY enters -> needs board TDP + $/kWh + deployment lifetime; at nominal efficiency energy/token ~EQUAL so sticker ranking is energy-robust, but under degraded efficiency the $799 sticker gap closes at ~387 days 24/7 and the ranking FLIPS)",
    "Q7 OUTPUT QUALITY / accuracy bar (criterion numerator P = RAW tokens/s silently treats every token as EQUALLY VALUABLE; quant trades throughput for ACCURACY (INT4 < INT8 < BF16 perplexity) -> R over-rewards the aggressive quant with ZERO quality penalty -> needs an acceptable-accuracy bar / eval-delta per quant; at a plausible tuned gap the ranking is quality-robust, but an un-tuned INT4 that fails a math/code eval flips it to the accurate config)",
    "Q8 LATENCY / TTFT (criterion numerator P = tokens/s is STEADY-STATE THROUGHPUT, a RATE with NO time dimension; task says RUN -> an INTERACTIVE deployed service must answer FAST -> a chat/agent user waits for the FIRST token (TTFT) which R never prices; TTFT is CARD-INDEPENDENT (prefill compute-bound, both cards ~equal peak flops) so the throughput ranking is LATENCY-ROBUST at equal prefill, BUT at SHORT generations TTFT DOMINATES end-to-end and the 5090's throughput edge is IRRELEVANT to the user -> needs: is the deployment interactive? max acceptable TTFT? typical generation length G)",
    "Q9 SUSTAINED / THERMAL-DERATE (criterion numerator P = tokens/s was computed from PEAK spec-sheet memory bandwidth, a BURST benchmark number; task says RUN -> a deployed service sustains 24/7 -> the card THERMALLY THROTTLES -> sustained bw < peak -> P is optimistic by a sustained_derate; the derate is CARD-SPECIFIC (consumer cards throttle harder than datacenter cards with better cooling/ECC) -> at plausible derates (5090 0.85 vs A100 0.95) the 5090's bw edge erodes 1.152x->1.031x (ranking sustained-robust, margin nearly gone) BUT a harsher consumer throttle (0.70) FLIPS the ranking to the sustained-steadier A100-40 -> needs: sustained soak bw / thermal envelope / duty cycle per card)",
    "Q10 DEPLOYMENT LIFETIME / OBSOLESCENCE RATE (criterion R=P/C ranks H* at TODAY's ratio and prices the card at STICKER, silently assuming the ranking is TIME-INVARIANT and the sticker is the whole cost; but a deployed RUN runs a LIFETIME L and the hardware FRONTIER keeps improving -> the incumbent's RELATIVE $/tok DECAYS at an obsolescence rate d/year -> the 'best buy today' is only best TODAY. The teeth: today's H*=A100-40 is a LEGACY card (EOL-adjacent, shortest remaining support) so it obsoletes FASTEST (d_a>d_s) -> its $/tok edge erodes -> over a deployment lifetime the ranking FLIPS to the newer RTX_5090; break-even ~2.4y -> any RUN longer than that makes the legacy cheap card the WRONG buy -> needs: deployment lifetime L + per-card obsolescence/support-decay rate)",
    "Q11 SYSTEM-LEVEL BOM / HOST-COST (criterion C(H*) has ALWAYS been a SINGLE-CARD sticker price, silently assuming the GPU is the whole bill; but task says RUN -> a deployed inference service is a SYSTEM -> the GPU cannot serve alone, it needs a HOST (CPU + motherboard + RAM + PSU + chassis + storage) -> a datacenter PCIe/SXM card needs a SERVER-class host while a consumer card rides a cheap desktop platform -> the cheap legacy H* carries the LARGER host premium -> its sticker edge ERODES at system level. At plausible host BOM (A100 server-class $800 vs 5090 desktop $400) the sticker gap $799 erodes to $399 (ranking host-cost-robust, A100 still cheaper $/tok) BUT a full server chassis/rack premium ($1800) FLIPS system $/tok to the consumer RTX_5090 -> needs: the non-card host BOM per deployment (server-class vs desktop) + whether the card must live in a rack)",
    "Q12 RESIDUAL VALUE / NET-COST-of-ownership (criterion C(H*) has ALWAYS been the GROSS sticker price, silently assuming the card is FULLY SUNK -- recovered to ZERO at end of life; but task says RUN -> a deployed card is SOLD AGAIN at end of life -> hardware retains RESIDUAL VALUE (resells at some fraction of sticker) -> true net cost = sticker*(1-resid) < sticker -> C OVER-counts the sunk cost -> the ranking is RESIDUAL-BLIND. The teeth: the consumer RTX_5090 holds value HARD (strong secondary market, gamers keep buying used) while the legacy datacenter A100-40 is EOL-adjacent and finds few buyers -> the consumer card recovers MORE residual -> at plausible residual (A100 0.20 vs 5090 0.30) the sticker $/tok gap $13.5 erodes to $7.3 (ranking residual-robust, A100 still cheaper net $/tok) BUT a strong consumer resale (5090 resid 0.75) FLIPS net $/tok to the consumer RTX_5090 -> the sticker-cheap legacy card is the WRONG buy when its sunk cost is netted against resale -> needs: the end-of-life residual/resale fraction per card (or equivalently the net cost of ownership)",
    "Q13 REPLICAS / REDUNDANCY / HA (criterion C(H*) has ALWAYS been the cost of EXACTLY ONE CARD, silently assuming the deployment is a SINGLE POINT OF FAILURE with zero redundancy; but task says RUN -> a deployed inference service for REAL USERS needs UPTIME -> production runs REPLICAS (N+1) -> true deployment cost = k*sticker -> C UNDER-COUNTED by the replica count -> the ranking is REPLICAS-BLIND. The teeth: the legacy datacenter A100-40 is EOL-adjacent with higher failure risk and thinner vendor support -> its redundancy must be ACTIVE-PASSIVE hot-standby (you cannot trust two old cards to both carry live traffic -> the standby is idle insurance, contributes ZERO throughput) -> fleet COST scales with replicas but fleet THROUGHPUT does NOT -> fleet $/tok DOUBLES; while a fresh consumer RTX_5090 runs ACTIVE-ACTIVE (or single) -> its redundancy is capacity not idle insurance. At plausible ACTIVE-ACTIVE redundancy the replica count CANCELS in $/tok (fleet $/tok A100 $21.9 < 5090 $35.4, ranking replicas-robust, H*=A100 today holds) BUT the legacy idle hot-standby FLIPS fleet $/tok to the consumer RTX_5090 ($21.9->$43.8 > $35.4) -> the sticker-cheap legacy card is the WRONG buy once you price the HA fleet -> needs: the production replica count per card / uptime SLA (and whether the redundancy is active-active or active-passive)",
    "Q14 SOFTWARE / LICENSING STACK COST (criterion C(H*) has ALWAYS been the cost of the PHYSICAL HARDWARE, silently assuming the SOFTWARE STACK you must run to serve a model is FREE; but task says RUN -> a deployed inference service runs OS + drivers + CUDA + inference engine + orchestration + monitoring, and much of that carries a LICENSE / support SUBSCRIPTION fee -> C UNDER-COUNTED by the software OPEX -> the ranking is SOFTWARE-BLIND. The teeth: the legacy datacenter A100-40 is EOL-adjacent -> it CANNOT run an unsupported free stack on live traffic -> it must rent a FULL commercial enterprise inference stack + enterprise OS support tied to its vendor support contract -> its software bill balloons; while a consumer RTX_5090 runs a FREE desktop stack (Ubuntu + open-source vLLM, no license fee). At a MODEST license the ranking is SOFTWARE-ROBUST (eff $/tok A100 $27.4 < 5090 $35.4, H*=A100 today holds) BUT the legacy card's forced enterprise-stack license FLIPS eff $/tok to the consumer RTX_5090 ($27.4->$40.2 > $35.4) -> the sticker-cheap legacy card is the WRONG buy once you price the SOFTWARE it must rent -> needs: the annual software+support license fee per card / whether the deployment runs a paid commercial stack or a free open-source stack)",
    "Q15 OPERATOR LABOR / OPS-PERSONNEL (criterion C(H*) has ALWAYS been the cost of the MACHINE -- a physical box or a contract -- silently assuming NO HUMAN ever touches the box; but task says RUN -> a deployed inference service is KEPT ALIVE by an OPERATOR (driver patching, failure triage, restart babysitting), and human labor costs money -> C UNDER-COUNTED by the ops-labor OPEX -> the ranking is LABOR-BLIND. The teeth: the legacy datacenter A100-40 is EOL-adjacent with NO vendor support and NO auto-heal -> a human must MANUALLY babysit it around the clock (hand-patch every driver, triage every failure, restart on every crash); while a consumer RTX_5090 rides an unattended hobbyist desktop nobody touches. At a MODEST operator-labor the ranking is LABOR-ROBUST (eff $/tok A100 $34.7 < 5090 $35.4, H*=A100 today holds) BUT the legacy card's forced continuous manual-babysitting labor FLIPS eff $/tok to the consumer RTX_5090 ($34.7->$49.3 > $35.4) -> the sticker-cheap legacy card is the WRONG buy once you price the OPERATOR who keeps it alive -> needs: the annual operator-labor / ops-personnel cost per card / whether the deployment is unattended or needs dedicated hands-on staff",
    "Q16 DEPLOYED-COST COMPOSITION / INTEGRATION MODEL (the FIRST META-ATTACK of the criterion, not a new cost term: every prior C-axis attack -- inv25 energy-content, inv29 temporal-decay, inv30 host-scope, inv31 residual-net, inv32 replica-multiplicity, inv43 software-composition, inv44 labor-basis -- added ONE thing to C IN ISOLATION and asked 'does THIS one flip the ranking?'; none ever STACKED them. But a real deployed RUN pays ALL seven AT ONCE, and R=P/C never checked whether they COMPOSE consistently: do their SIGNS agree, does any DOUBLE-COUNT the same dollar, and does the FULL cumulative load finally FLIP? The audit: stacking sticker + host(+one-time CAPEX) - sticker*resid(-terminal credit) + energy(+recurring physical OPEX) + software(+recurring contractual OPEX) + labor(+recurring human OPEX) decomposes into 6 mutually-distinct signed terms -> no double-count, signs consistent -> the seven COMPOSE cleanly. KEY finding invisible to every single-axis view: inv25 found ENERGY PER TOKEN ~EQUAL (throughput~power offset) BUT stacked over the deployment LIFETIME the FASTER 5090 serves ~2x more tokens -> its TOTAL energy bill is ~2x the A100's ($3211 vs $1560) -> per-token parity does NOT imply lifetime-TOTAL parity, the asymmetry lives in the INTEGRATION not in any single axis. At nominal add-ons the ranking is INTEGRATION-ROBUST (total deployed $/tok A100 $73.5 < 5090 $88.8, H*=A100 today survives the cumulative load) BUT when the legacy card pays EVERY add-on at its WORST simultaneously (server rack host + rented enterprise software + manual-babysitting labor) the FULL stack FLIPS total deployed $/tok to the consumer RTX_5090 ($73.5->$119.2 > $88.8) -> the sticker-cheap legacy card is the WRONG buy under the TOTAL deployed cost -> needs: the full deployed-cost COMPOSITION / INTEGRATION MODEL -- how the axes combine (additive vs multiplicative), their signs, whether energy scales with lifetime, whether replicas multiply the whole stack",
    "Q17 USEFUL-THROUGHPUT NUMERATOR COMPOSITION MODEL (the SECOND META-ATTACK of the criterion, the MIRROR of inv45/Q16 which audited the DENOMINATOR's seven C-axes: every prior P-side attack -- inv8..25 size/count, inv26 output-quality weight, inv27 latency/TTFT dimension, inv28 sustained/thermal derate -- adjusted the NUMERATOR P IN ISOLATION and asked 'does THIS one erode or flip the ranking?'; none ever STACKED them. But a real deployed RUN pays the sustained thermal derate AND the quality weight AT ONCE on the same card, and R=P/C never checked whether the two MULTIPLICATIVE numerator discounts COMPOSE consistently: do their SIGNS agree, does any DOUBLE-COUNT the same throughput haircut, and does the FULL cumulative derate finally FLIP? The audit: the two discounts hit DISTINCT substances -- the sustained derate multiplies the PHYSICAL rate (bw, thermal physics), the quality weight multiplies the SEMANTIC token VALUE (accuracy) -- so they COMPOSE multiplicatively, no double-count. KEY finding invisible to any single axis: inv28 saw the consumer 5090 STILL LEAD at sustained (edge 1.238x) and inv26 saw quality CAN flip at aggressive quant, but NEITHER stacked them; the single-axis R_sustained (0.0564) and the composed R_useful (0.0536) differ by EXACTLY the quality factor 0.950 that inv26 added and inv28 NEVER applied -> the consumer card is penalized TWICE. At nominal the ranking is NUMERATOR-COMPOSITION-ROBUST (composed edge 1.200x, eroded from raw 1.384x, 5090 still leads) BUT when the consumer pays BOTH penalties at their WORST simultaneously (harsher sustained throttle 0.85->0.70 AND un-tuned aggressive INT4 quality 0.95->0.70) the FULL cumulative derate finally FLIPS the composed edge to the accurate datacenter A100-40 (1.200x->0.728x < 1) -> the peak-fast aggressive-quant consumer card is the WRONG buy once you stack the thermal AND quality haircuts it pays -> needs: the full USEFUL-throughput COMPOSITION MODEL -- how the sustained derate and the quality weight combine on P (multiplicative vs additive), whether they double-count, whether the cumulative derate flips the ranking",
    "Q18 RATIO-BASIS / DIMENSIONAL COMMENSURABILITY MODEL (the THIRD META-ATTACK of the criterion. inv45 audited whether the seven DENOMINATOR C-axes COMPOSE and inv46 audited whether the NUMERATOR's adjustments COMPOSE -- BOTH ASSUMED the two SIDES are even LEGAL to divide. But P = tokens/s is a FLOW (a per-second RATE, dimension T^-1) while C = price is a STOCK (a one-time capital $, NO time dimension). R = tokens/(s*$) divides a RATE by a LUMP-SUM, which silently fixes the value horizon at exactly ONE SECOND of service per dollar -- yet task says RUN -> a deployed card serves for YEARS (Q10). The dimensionally-commensurate quantity is R_life = (P x T_sec)/C = lifetime tokens/$ (a STOCK/STOCK ratio in which the time dimension cancels). This attacks the criterion's UNIT BASIS -- a structural property DISTINCT from inv45/inv46 (those audited composition WITHIN one side; this audits commensurability BETWEEN the two sides) and DISTINCT from inv27 (that attacked the numerator's latency dimension TTFT, not the flow-vs-stock mismatch) and inv29 (that decayed the denominator's PRICE over time, not the numerator's need to be integrated over the horizon). KEY finding invisible to any single axis: R_rate and R_life differ by EXACTLY the horizon factor T_sec (~1.58e8 s over 5y) -- R=P/C silently assumed the card delivers exactly ONE second of throughput per dollar. At a COMMON horizon the ranking is DIMENSIONALLY-ROBUST (the common T_sec cancels, who-wins unchanged, H*=5090-batched today holds) BUT the numeric VALUE of R is horizon-dependent (a rate-basis number is NOT comparable across horizons); and when the horizon is PER-CARD (the consumer RTX_5090 rides a consumer platform that obsoletes FASTER -> shorter usable lifetime 2y vs the datacenter A100-40's 8y enterprise support), R_life applies a per-card horizon factor R_rate NEVER applied -> the consumer's shorter lifespan penalizes it AGAIN -> the per-card horizon finally FLIPS the lifetime-basis edge (1.200x->0.300x < 1) to the longer-lived datacenter A100-40 -> the fast-but-short-lived consumer card is the WRONG buy once you integrate throughput over each card's OWN horizon -> needs: the full RATIO-BASIS MODEL -- rate-basis tokens/s-per-$ vs lifetime-stock-basis tokens-per-$, and whether the deployment horizon is COMMON to both cards or PER-CARD",
}
if "Q4 batch size" not in " ".join(REQUIRED_INPUTS): fails.append("inv22: batch NOT declared a required input -> the tree silently assumes batch=1")
if "Q5 working-sequence-length" not in " ".join(REQUIRED_INPUTS): fails.append("inv23: working-sequence-length NOT declared a required input -> the tree silently assumes CTX=8K (5090 INT8 overflows at 128K input)")
if "Q6 ENERGY" not in " ".join(REQUIRED_INPUTS): fails.append("inv25: ENERGY/TCO NOT declared a required input -> the tree silently prices H* on sticker only, ignoring electricity a deployed card pays for its whole lifetime")
if "Q7 OUTPUT QUALITY" not in " ".join(REQUIRED_INPUTS): fails.append("inv26: OUTPUT QUALITY NOT declared a required input -> the tree ranks H* on RAW tokens/s, silently treating every token as equally valuable, ignoring that a deployed RUN must produce ACCURATE tokens and quant trades throughput for accuracy")
if "Q8 LATENCY" not in " ".join(REQUIRED_INPUTS): fails.append("inv27: LATENCY/TTFT NOT declared a required input -> the tree ranks H* on STEADY-STATE THROUGHPUT (tokens/s, a RATE with no time dimension), silently assuming a BATCH job where no one waits; task says RUN -> an INTERACTIVE deployed service must answer FAST -> TTFT is the user experience and is never priced")
